<section class="admin-head"><div><span class="kicker">BIBLIOTECA</span><h1>SUBIR FOTOS POR LOTES</h1></div><a href="<?=url('admin')?>">← Resumen</a></section><section class="panel"><form class="uploader" method="post" enctype="multipart/form-data"><input type="hidden" name="_token" value="<?=csrf()?>"><label>Evento<select name="event_id" required><?php foreach($events as $e):?><option value="<?=$e['id']?>"><?=htmlspecialchars($e['name'])?></option><?php endforeach;?></select></label><label>Nº competidor<input name="bib_number" placeholder="Ej. 184"></label><label>Precio CLP<input name="price" type="number" value="4990"></label><label class="drop">Selecciona múltiples JPG, PNG o WebP<input type="file" name="photos[]" accept="image/*" multiple required></label><label class="check"><input type="checkbox" name="watermark" checked> Aplicar marca de agua a la vista previa</label><label class="check"><input type="checkbox" name="download_enabled" checked> Habilitar descarga después del pago</label><button class="primary">PROCESAR LOTE →</button></form></section><section class="panel"><h2>Últimas fotos</h2><div class="table"><?php foreach($photos as $p):?><div><img src="<?=url($p['preview_path'])?>"><span><b><?=htmlspecialchars($p['title'])?></b><small><?=htmlspecialchars($p['event_name'])?> · #<?=htmlspecialchars($p['bib_number'])?></small></span><em><?=$p['watermark_enabled']?'Marca activa':'Sin marca'?></em><form method="post" action="<?=url('admin/fotos/descarga')?>"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="enabled" value="<?=$p['download_enabled']?0:1?>"><button><?=$p['download_enabled']?'Bloquear':'Habilitar'?> descarga</button></form></div><?php endforeach;?></div></section>

